const STORAGE_KEY_PROPERTIES = 'hunianisme_properties_v2';
const STORAGE_KEY_ARTICLES = 'hunianisme_articles_v2';
const STORAGE_KEY_ADMIN_AUTH = 'hunianisme_admin_auth_v2';
const STORAGE_KEY_SITE_SETTINGS = 'hunianisme_site_settings_v2';
const STORAGE_KEY_DEMO_CLEARED = 'hunianisme_demo_cleared_v2';

export function getSiteSettings(): SiteSettings {
  if (typeof window === 'undefined') return DEFAULT_SITE_SETTINGS;
  try {
    const data = localStorage.getItem(STORAGE_KEY_SITE_SETTINGS);
    if (!data) return DEFAULT_SITE_SETTINGS;
    const parsed = JSON.parse(data);
    // Sanitize logoUrl so invalid values like '--turbopack' or malformed URLs are cleaned
    if (parsed.logoUrl && !isValidImageUrl(parsed.logoUrl)) {
      parsed.logoUrl = '';
    }
    const faviconUrl = isValidImageUrl(parsed.faviconUrl)
      ? parsed.faviconUrl.trim()
      : (DEFAULT_SITE_SETTINGS.faviconUrl || '');
    return { ...DEFAULT_SITE_SETTINGS, ...parsed, faviconUrl };
  } catch {
    return DEFAULT_SITE_SETTINGS;
  }
}

export function saveSiteSettings(settings: SiteSettings): void {
  if (typeof window === 'undefined') return;
  try {
    const cleanSettings: SiteSettings = {
      ...settings,
      logoUrl: isValidImageUrl(settings.logoUrl) ? settings.logoUrl.trim() : '',
      faviconUrl: isValidImageUrl(settings.faviconUrl)
        ? settings.faviconUrl.trim()
        : (DEFAULT_SITE_SETTINGS.faviconUrl || ''),
    };
    localStorage.setItem(STORAGE_KEY_SITE_SETTINGS, JSON.stringify(cleanSettings));
    window.dispatchEvent(new CustomEvent('hunianisme_data_changed', { detail: { type: 'settings' } }));
    syncDataToServer({ settings: cleanSettings });
  } catch (err) {
    console.error('Failed to save site settings', err);
  }
}

export function formatRupiah(amount: number): string {
  if (amount >= 1000000000) {
    const milyar = (amount / 1000000000).toLocaleString('id-ID', {
      minimumFractionDigits: amount % 1000000000 === 0 ? 0 : 2,
      maximumFractionDigits: 2,
    });
    return `Rp ${milyar} Milyar`;
  }
  if (amount >= 1000000) {
    const juta = (amount / 1000000).toLocaleString('id-ID', {
      minimumFractionDigits: 0,
      maximumFractionDigits: 1,
    });
    return `Rp ${juta} Juta`;
  }
  return `Rp ${amount.toLocaleString('id-ID')}`;
}

export function calculateKPR(
  price: number,
  dpPercent: number,
  interestAnnual: number,
  tenorYears: number
) {
  const dpAmount = Math.round((price * dpPercent) / 100);
  const loanAmount = Math.max(0, price - dpAmount);
  const totalMonths = tenorYears * 12;
  const monthlyRate = interestAnnual / 100 / 12;

  let monthlyInstallment = 0;
  if (monthlyRate === 0 || totalMonths === 0) {
    monthlyInstallment = loanAmount / (totalMonths || 1);
  } else {
    // Formula anuitas KPR: M = P * [r(1+r)^n] / [(1+r)^n - 1]
    const factor = Math.pow(1 + monthlyRate, totalMonths);
    monthlyInstallment = Math.round((loanAmount * (monthlyRate * factor)) / (factor - 1));
  }

  return {
    propertyPrice: price,
    downPaymentPercent: dpPercent,
    downPaymentAmount: dpAmount,
    loanAmount,
    interestRate: interestAnnual,
    tenorYears,
    monthlyInstallment,
  };
}

// STORAGE HELPERS (Safe for SSR and Client)
export function getStoredProperties(): PropertyListing[] {
  if (typeof window === 'undefined') return [];
  try {
    const data = localStorage.getItem(STORAGE_KEY_PROPERTIES);
    if (data === null) {
      localStorage.setItem(STORAGE_KEY_PROPERTIES, JSON.stringify([]));
      return [];
    }
    const parsed = JSON.parse(data);
    const list = Array.isArray(parsed) ? parsed : [];
    return list.map((item) => ({
      ...item,
      type: item.type === 'proyek-baru' ? 'rumah' : item.type,
      badge: item.type === 'proyek-baru' && !item.badge ? 'Proyek Baru' : item.badge,
      imageUrl: sanitizeImageUrl(item.imageUrl, ''),
      additionalImages: Array.isArray(item.additionalImages)
        ? item.additionalImages.filter(isValidImageUrl)
        : [],
    }));
  } catch {
    return [];
  }
}

export async function syncDataToServer(payload: {
  properties?: PropertyListing[];
  articles?: Article[];
  settings?: SiteSettings;
}): Promise<boolean> {
  if (typeof window === 'undefined') return false;
  try {
    const res = await fetch('/api/sync', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    });
    return res.ok;
  } catch (err) {
    console.warn('Sync to server failed', err);
    return false;
  }
}

export async function fetchServerDataAndSync(): Promise<{
  properties: PropertyListing[] | null;
  articles: Article[] | null;
  settings: SiteSettings | null;
}> {
  if (typeof window === 'undefined') return { properties: null, articles: null, settings: null };
  try {
    const res = await fetch('/api/sync');
    if (!res.ok) return { properties: null, articles: null, settings: null };
    const data = await res.json();
    let changed = false;

    // Purge deprecated legacy storage keys
    try {
      localStorage.removeItem('hunianisme_properties_v1');
      localStorage.removeItem('hunianisme_articles_v1');
    } catch {
      // ignore
    }

    // Handle settings synchronization intelligently:
    const localSettingsRaw = localStorage.getItem(STORAGE_KEY_SITE_SETTINGS);
    if (localSettingsRaw) {
      try {
        const localSettings = JSON.parse(localSettingsRaw);
        const hasCustomLogo = isValidImageUrl(localSettings.logoUrl);
        const hasCustomBrand = localSettings.brandName && localSettings.brandName !== DEFAULT_SITE_SETTINGS.brandName;
        const hasCustomWA = localSettings.contactWhatsapp && localSettings.contactWhatsapp !== DEFAULT_SITE_SETTINGS.contactWhatsapp;
        const hasCustomEmail = localSettings.contactEmail && localSettings.contactEmail !== DEFAULT_SITE_SETTINGS.contactEmail;
        const hasCustomAddr = localSettings.officeAddress && localSettings.officeAddress !== DEFAULT_SITE_SETTINGS.officeAddress;

        if (hasCustomLogo || hasCustomBrand || hasCustomWA || hasCustomEmail || hasCustomAddr) {
          // Client has customized settings: make sure they are synced to server
          if (JSON.stringify(data.settings) !== JSON.stringify(localSettings)) {
            syncDataToServer({ settings: localSettings });
          }
        } else if (data.settings && typeof data.settings === 'object') {
          localStorage.setItem(STORAGE_KEY_SITE_SETTINGS, JSON.stringify(data.settings));
          changed = true;
        }
      } catch {
        if (data.settings && typeof data.settings === 'object') {
          localStorage.setItem(STORAGE_KEY_SITE_SETTINGS, JSON.stringify(data.settings));
          changed = true;
        }
      }
    } else if (data.settings && typeof data.settings === 'object') {
      localStorage.setItem(STORAGE_KEY_SITE_SETTINGS, JSON.stringify(data.settings));
      changed = true;
    }

    // Handle properties synchronization safely without data loss:
    try {
      const localPropsRaw = localStorage.getItem(STORAGE_KEY_PROPERTIES);
      const localProps = localPropsRaw ? JSON.parse(localPropsRaw) : null;
      if (Array.isArray(localProps) && localProps.length > 0) {
        if (!Array.isArray(data.properties) || data.properties.length === 0) {
          syncDataToServer({ properties: localProps });
        }
      } else if (localProps === null && Array.isArray(data.properties) && data.properties.length > 0) {
        localStorage.setItem(STORAGE_KEY_PROPERTIES, JSON.stringify(data.properties));
        changed = true;
      }
    } catch {
      // ignore
    }

    // Handle articles synchronization safely without data loss:
    try {
      const localArtsRaw = localStorage.getItem(STORAGE_KEY_ARTICLES);
      const localArts = localArtsRaw ? JSON.parse(localArtsRaw) : null;
      if (!Array.isArray(localArts) || localArts.length === 0) {
        if (Array.isArray(data.articles) && data.articles.length > 0) {
          localStorage.setItem(STORAGE_KEY_ARTICLES, JSON.stringify(data.articles));
          changed = true;
        } else if (INITIAL_ARTICLES.length > 0 && localStorage.getItem(STORAGE_KEY_DEMO_CLEARED) !== 'true') {
          localStorage.setItem(STORAGE_KEY_ARTICLES, JSON.stringify(INITIAL_ARTICLES));
          changed = true;
        }
      } else if (Array.isArray(data.articles) && data.articles.length > 0) {
        let updated = false;
        const merged = localArts.map((art: Article) => {
          const serverArt = data.articles.find((sa: Article) => sa.id === art.id || sa.slug === art.slug);
          if (serverArt && (
            serverArt.imageUrl !== art.imageUrl || 
            serverArt.title !== art.title || 
            serverArt.content !== art.content ||
            serverArt.metaTitle !== art.metaTitle ||
            serverArt.metaDescription !== art.metaDescription ||
            serverArt.focusKeywords !== art.focusKeywords
          )) {
            updated = true;
            return { ...art, ...serverArt };
          }
          return art;
        });
        for (const sa of data.articles) {
          if (!merged.some((a: Article) => a.id === sa.id || a.slug === sa.slug)) {
            merged.push(sa);
            updated = true;
          }
        }
        if (updated) {
          localStorage.setItem(STORAGE_KEY_ARTICLES, JSON.stringify(merged));
          changed = true;
        }
      }
    } catch {
      // ignore
    }

    if (changed) {
      window.dispatchEvent(new CustomEvent('hunianisme_data_changed', { detail: { type: 'server_sync' } }));
    }

    return data;
  } catch (err) {
    console.warn('Failed to fetch server data', err);
    return { properties: null, articles: null, settings: null };
  }
}

export function saveProperties(properties: PropertyListing[]): void {
  if (typeof window === 'undefined') return;
  try {
    const sanitized = properties.map((item) => ({
      ...item,
      imageUrl: sanitizeImageUrl(item.imageUrl, ''),
      additionalImages: Array.isArray(item.additionalImages)
        ? item.additionalImages.filter(isValidImageUrl)
        : [],
    }));
    localStorage.setItem(STORAGE_KEY_PROPERTIES, JSON.stringify(sanitized));
    window.dispatchEvent(new CustomEvent('hunianisme_data_changed', { detail: { type: 'properties' } }));
    // Automatically persist to server for public site
    syncDataToServer({ properties: sanitized });
  } catch (err) {
    console.error('Failed to save properties', err);
  }
}

export function getStoredArticles(): Article[] {
  if (typeof window === 'undefined') return INITIAL_ARTICLES;
  try {
    const data = localStorage.getItem(STORAGE_KEY_ARTICLES);
    const isCleared = localStorage.getItem(STORAGE_KEY_DEMO_CLEARED) === 'true';
    if (data === null) {
      if (!isCleared && INITIAL_ARTICLES.length > 0) {
        localStorage.setItem(STORAGE_KEY_ARTICLES, JSON.stringify(INITIAL_ARTICLES));
        return INITIAL_ARTICLES;
      }
      localStorage.setItem(STORAGE_KEY_ARTICLES, JSON.stringify([]));
      return [];
    }
    const parsed = JSON.parse(data);
    const list = Array.isArray(parsed) ? parsed : [];
    if (list.length === 0 && !isCleared && INITIAL_ARTICLES.length > 0) {
      localStorage.setItem(STORAGE_KEY_ARTICLES, JSON.stringify(INITIAL_ARTICLES));
      return INITIAL_ARTICLES;
    }
    return list.map((item) => ({
      ...item,
      imageUrl: sanitizeImageUrl(item.imageUrl, ''),
    }));
  } catch {
    return INITIAL_ARTICLES;
  }
}

export function saveArticles(articles: Article[]): void {
  if (typeof window === 'undefined') return;
  try {
    const sanitized = articles.map((item) => ({
      ...item,
      imageUrl: sanitizeImageUrl(item.imageUrl, ''),
    }));
    localStorage.setItem(STORAGE_KEY_ARTICLES, JSON.stringify(sanitized));
    window.dispatchEvent(new CustomEvent('hunianisme_data_changed', { detail: { type: 'articles' } }));
    // Automatically persist to server for public site
    syncDataToServer({ articles: sanitized });
  } catch (err) {
    console.error('Failed to save articles', err);
  }
}

// ADMIN AUTHENTICATION (Direct Access Enabled - No password or login required)
export function isAdminLoggedIn(): boolean {
  return true;
}

export function setAdminLogin(isLoggedIn: boolean, email: string = 'admin@hunianisme.com'): void {
  if (typeof window === 'undefined') return;
  try {
    if (isLoggedIn) {
      localStorage.setItem(
        STORAGE_KEY_ADMIN_AUTH,
        JSON.stringify({
          isLoggedIn: true,
          email,
          name: 'Administrator Hunianisme',
          role: 'Super Admin',
          loginTime: new Date().toISOString(),
        })
      );
    } else {
      localStorage.removeItem(STORAGE_KEY_ADMIN_AUTH);
    }
    window.dispatchEvent(new CustomEvent('hunianisme_auth_changed'));
  } catch (err) {
    console.error('Failed to set admin auth', err);
  }
}

export function getAdminUser() {
  if (typeof window === 'undefined') return null;
  try {
    const auth = localStorage.getItem(STORAGE_KEY_ADMIN_AUTH);
    return auth ? JSON.parse(auth) : null;
  } catch {
    return null;
  }
}

export function clearAllDemoSamples(): void {
  if (typeof window === 'undefined') return;
  // Mark demo as explicitly cleared so default samples never automatically re-appear
  localStorage.setItem(STORAGE_KEY_DEMO_CLEARED, 'true');
  localStorage.setItem(STORAGE_KEY_PROPERTIES, JSON.stringify([]));
  localStorage.setItem(STORAGE_KEY_ARTICLES, JSON.stringify([]));
  window.dispatchEvent(new CustomEvent('hunianisme_data_changed', { detail: { type: 'all' } }));
  syncDataToServer({ properties: [], articles: [] });
}

export function resetAllDataToDefault(): void {
  // Completely empty all listings and articles data without any remainder
  clearAllDemoSamples();
}

export function restoreDemoSamples(): void {
  // No-op: samples intentionally removed per user specification
}

// SLUG & LOOKUP HELPERS
export function slugify(text: string): string {
  if (!text) return '';
  return text
    .toString()
    .toLowerCase()
    .trim()
    .replace(/\s+/g, '-')
    .replace(/[^\w-]+/g, '')
    .replace(/--+/g, '-')
    .replace(/^-+/, '')
    .replace(/-+$/, '');
}

export function getPropertySlug(property: PropertyListing): string {
  if (property.slug && property.slug.trim().length > 0) {
    return property.slug;
  }
  return slugify(property.title) || property.id;
}

export function getArticleSlug(article: Article): string {
  if (article.slug && article.slug.trim().length > 0) {
    return article.slug;
  }
  return slugify(article.title) || article.id;
}

export function getPropertyBySlugOrId(slugOrId: string, propertiesList?: PropertyListing[]): PropertyListing | null {
  const list = propertiesList || getStoredProperties();
  if (!list || list.length === 0) return null;
  const decoded = decodeURIComponent(slugOrId).toLowerCase().trim();
  return list.find((p) => {
    const pSlug = getPropertySlug(p).toLowerCase();
    const pId = (p.id || '').toLowerCase();
    const titleSlug = slugify(p.title).toLowerCase();
    return pSlug === decoded || pId === decoded || titleSlug === decoded;
  }) || null;
}

export function getArticleBySlugOrId(slugOrId: string, articlesList?: Article[]): Article | null {
  const list = articlesList || getStoredArticles();
  if (!list || list.length === 0) return null;
  const decoded = decodeURIComponent(slugOrId).toLowerCase().trim();
  return list.find((a) => {
    const aSlug = getArticleSlug(a).toLowerCase();
    const aId = (a.id || '').toLowerCase();
    const titleSlug = slugify(a.title).toLowerCase();
    return aSlug === decoded || aId === decoded || titleSlug === decoded;
  }) || null;
}

